async def act(page):
    """
    Complete the product creation: set Price to 769.99, Inventory Qty to 42 and Stock Availability to In Stock,
    attempt to set Size = "uni-size" and Color = "Blue" if those attribute controls exist, then Save the product.

    The final action (Save) triggers navigation, so it is the last call in this function.
    """
    # Ensure the form is ready and Save is visible before interacting
    await page.get_by_role("button", name="Save").wait_for(state="visible")

    # 1) Prices tab -> set Price to 769.99
    try:
        await page.get_by_role("link", name="Prices").click()
        await page.get_by_role("textbox", name="Price").wait_for(state="visible", timeout=3000)
        await page.get_by_role("textbox", name="Price").fill("769.99")
    except Exception:
        # If Price field/tab not found or issues, continue — we'll still attempt inventory & save
        pass

    # 2) Inventory tab -> set Qty = 42 and Stock Availability = In Stock
    try:
        await page.get_by_role("link", name="Inventory").click()
        # Try common accessible names for the Qty field to be robust
        qty_set = False
        for qty_name in ("Qty", "Qty *", "Qty*", "Quantity"):
            try:
                tb = page.get_by_role("textbox", name=qty_name)
                await tb.wait_for(state="visible", timeout=1000)
                await tb.fill("42")
                qty_set = True
                break
            except Exception:
                continue
        # If none matched, attempt to fill any textbox likely to accept qty (best-effort fallback)
        if not qty_set:
            try:
                all_textboxes = page.get_by_role("textbox")
                count = await all_textboxes.count()
                for i in range(count):
                    tb = all_textboxes.nth(i)
                    try:
                        await tb.fill("42")
                        break
                    except Exception:
                        continue
            except Exception:
                pass

        # Set Stock Availability to "In Stock"
        try:
            await page.get_by_role("combobox", name="Stock Availability").select_option(label="In Stock")
        except Exception:
            try:
                await page.get_by_role("combobox", name="Stock Availability").select_option("In Stock")
            except Exception:
                pass
    except Exception:
        # If Inventory tab not available, continue
        pass

    # 3) Return to General tab and attempt to set Size and Color attributes if present
    try:
        await page.get_by_role("link", name="General").click()
        await page.get_by_role("textbox", name="Name *").wait_for(state="visible", timeout=3000)
    except Exception:
        pass

    # Size = uni-size (if present)
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="uni-size")
    except Exception:
        try:
            await page.get_by_role("combobox", name="Size").select_option("uni-size")
        except Exception:
            pass

    # Color = Blue (if present)
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="Blue")
    except Exception:
        try:
            await page.get_by_role("combobox", name="Color").select_option("Blue")
        except Exception:
            pass

    # 4) Save the product (navigation) - last action
    await page.get_by_role("button", name="Save").click()

